input.command:
mysql --defaults-extra-file=~/.dc-platform/secrets/my.cnf.prod -N -e "
SELECT app_id, min_threshold, brand_score, model_score, system_name, system_version, is_active, is_run
FROM dim.dim_app_attribution_config WHERE app_id='default';
SELECT app_id, max_seconds, score FROM dim.dim_app_attribution_time_config WHERE app_id='default' AND COALESCE(is_active,1)=1 ORDER BY max_seconds;
"
